// Cross-checks lib/core/crypto/vault_crypto.dart against a fixed test
// vector generated by passvault-client's exact algorithm running under
// Node's WebCrypto (see scratch/gen_vector.mjs) -- WebCrypto is spec-
// identical whether it runs in Node or a browser, so matching this vector
// means this app's vault key derivation and blob encryption/decryption are
// interoperable with passvault-client's for the same account.
import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:passvault_mobile/core/crypto/vault_crypto.dart';

void main() {
  // Vector from scratch/gen_vector.mjs.
  const kdfSalt = 'MDEyMzQ1Njc4OWFiY2RlZg==';
  const vaultPassword = 'correct horse battery staple';
  const ivBase64 = 'BwcHBwcHBwcHBwcH';
  final plaintextObject = {
    'entries': [
      {'id': '1', 'type': 1, 'title': 'Test Account', 'username': 'alice'},
    ],
  };
  const expectedVaultKey = 'H/ZMdkjDEDpZ4T7DlMYQs7RkF9UgyowFSsi/pzKxi+s=';
  const expectedBlob =
      'BwcHBwcHBwcHBwcHrfU4h08l4vXoV5E1VQ+xRSzP2NgIVotNrvCCzg8vuXNSYlAp6qs40IHF28okR35nnUVMIb6n5YxkeC7hwWihxcU14IxlWeI/5CGaDttBfMr1wtgDhv1PLl30oA==';

  test('deriveVaultKeyFromPassword matches WebCrypto PBKDF2 output', () {
    final key = deriveVaultKeyFromPassword(vaultPassword, kdfSalt);
    expect(key, expectedVaultKey);
  });

  test('encryptVaultBlobWithIv matches WebCrypto AES-GCM output byte-for-byte', () {
    final iv = base64Decode(ivBase64);
    final blob = encryptVaultBlobWithIv(expectedVaultKey, plaintextObject, Uint8List.fromList(iv));
    expect(blob, expectedBlob);
  });

  test('decryptVaultBlob reads a blob produced by WebCrypto', () {
    final decrypted = decryptVaultBlob(expectedVaultKey, expectedBlob);
    expect(decrypted, plaintextObject);
  });

  test('encryptVaultBlob / decryptVaultBlob round-trip with a random IV', () {
    final blob = encryptVaultBlob(expectedVaultKey, plaintextObject);
    final decrypted = decryptVaultBlob(expectedVaultKey, blob);
    expect(decrypted, plaintextObject);
  });

  test('decryptVaultBlob rejects a tampered blob', () {
    final bytes = base64Decode(expectedBlob);
    bytes[bytes.length - 1] ^= 0xFF; // flip a bit in the GCM tag
    expect(
      () => decryptVaultBlob(expectedVaultKey, base64Encode(bytes)),
      throwsA(anything),
    );
  });

  // Key check made by passvault-client's createKeyCheck (WebCrypto, random IV)
  // for expectedVaultKey -- both apps must accept each other's checks.
  const webKeyCheck = '5o6mBDRSVHE2vREZ65NJUKU32l0+jFxwT84bP5tZB7/ArzBLRBPJeDRAJGw/HzszapU9e3kdOy1orPsTZTQ=';

  test('verifyKeyCheck accepts a key check made by the web client', () {
    expect(verifyKeyCheck(expectedVaultKey, webKeyCheck), isTrue);
  });

  test('verifyKeyCheck rejects the wrong key', () {
    final wrongKey = deriveVaultKeyFromPassword('wrong password', kdfSalt);
    expect(verifyKeyCheck(wrongKey, webKeyCheck), isFalse);
    expect(verifyKeyCheck(wrongKey, createKeyCheck(expectedVaultKey)), isFalse);
  });

  test('createKeyCheck round-trips', () {
    expect(verifyKeyCheck(expectedVaultKey, createKeyCheck(expectedVaultKey)), isTrue);
  });
}
